590	// saveExclusive 创建新文件，目标已存在即失败（O_EXCL）。
591	func (m *Map) saveExclusive() error {
592		data, err := encodeFile(m.state)
593		if err != nil {
594			return err
595		}
596		f, err := os.OpenFile(m.path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
597		if err != nil {
598			return err
599		}
600		return writeAndClose(f, data, m.path)
601	}
